+package redis
+
+import (
+	"crypto/tls"
+	"crypto/x509"
+	"fmt"
+	"os"
+
+	goredis "github.com/redis/go-redis/v9"
+	"go.flipt.io/flipt/internal/config"
+)
+
+// NewClient constructs a redis client from the provided configuration.
+// When RequireTLS is set, the connection uses TLS 1.2 or newer. Trust is
+// established from CaCertBytes or CaCertPath when provided, otherwise the
+// system certificate authorities are used. InsecureSkipTLS disables
+// certificate verification.
+func NewClient(cfg config.RedisCacheConfig) (*goredis.Client, error) {
+	var tlsConfig *tls.Config
+	if cfg.RequireTLS {
+		tlsConfig = &tls.Config{
+			MinVersion: tls.VersionTLS12,
+		}
+
+		if cfg.InsecureSkipTLS {
+			tlsConfig.InsecureSkipVerify = true // #nosec G402 -- explicitly requested by config
+		} else {
+			pem, err := caBundle(cfg)
+			if err != nil {
+				return nil, err
+			}
+			if len(pem) > 0 {
+				pool := x509.NewCertPool()
+				if !pool.AppendCertsFromPEM(pem) {
+					return nil, fmt.Errorf("failed to parse CA certificate for redis")
+				}
+				tlsConfig.RootCAs = pool
+			}
+		}
+	}
+
+	return goredis.NewClient(&goredis.Options{
+		Addr:            fmt.Sprintf("%s:%d", cfg.Host, cfg.Port),
+		TLSConfig:       tlsConfig,
+		Username:        cfg.Username,
+		Password:        cfg.Password,
+		DB:              cfg.DB,
+		PoolSize:        cfg.PoolSize,
+		MinIdleConns:    cfg.MinIdleConn,
+		ConnMaxIdleTime: cfg.ConnMaxIdleTime,
+		DialTimeout:     cfg.NetTimeout,
+		ReadTimeout:     cfg.NetTimeout * 2,
+		WriteTimeout:    cfg.NetTimeout * 2,
+		PoolTimeout:     cfg.NetTimeout * 2,
+	}), nil
+}
+
+func caBundle(cfg config.RedisCacheConfig) ([]byte, error) {
+	if cfg.CaCertBytes != "" {
+		return []byte(cfg.CaCertBytes), nil
+	}
+	if cfg.CaCertPath != "" {
+		return os.ReadFile(cfg.CaCertPath)
+	}
+	return nil, nil
+}

